
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_golden_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_golden", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.827155417416897e+01, 9.460954058648697e+01, 8.960168960002876e+01, 8.290285156874836e+01, 7.422067232053801e+01, 6.346384926272818e+01, 5.096238671956337e+01, 3.768277962809697e+01, 2.521306070215162e+01, 1.511621575870806e+01, 7.384498984601694e+00, 2.730964151065299e+00, 1.961632453543223e+00, 1.369723913659199e+00, 7.783143431255454e-01, 4.013987645923905e-01, 2.420636341819364e-01, 1.914802150879137e-01, 1.745350497888855e-01, 1.659254942198461e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


